#include <iostream>
#include <map>
using namespace std;

map<pair<int, int>, long long> all;
map<tuple<int, int, int>, long long> limit;
int n = 0, m = 0;

long long searchall(int l, int h) {
    if (l == h) {
        return 1;
    }
    auto key = make_pair(l, h);
    if (all.count(key)) {
        return all[key];
    }
    all[key] = 0;
    all[key] += searchall(l + 1, h);
    all[key] += searchall(l, h - 1);
    for (int i = l + 1; i < h; ++i) {
        all[key] += searchall(l, i - 1) * searchall(i + 1, h);
    }
    return all[key];
}

long long searchlimit(int l, int h, int d) {
    if (l == h) {
        return (d < m) ? 1 : 0;
    }
    auto key = make_tuple(l, h, d);
    if (limit.count(key)) {
        return limit[key];
    }
    limit[key] = 0;
    limit[key] += searchlimit(l + 1, h, d + 1);
    limit[key] += searchlimit(l, h - 1, d + 1);
    for (int i = l + 1; i < h; ++i) {
        limit[key] += searchlimit(l, i - 1, d + 1) * searchlimit(i + 1, h, d + 1);
    }
    return limit[key];
}

int main() {
    cin >> n >> m;
    long long res = searchall(1, n) - searchlimit(1, n, 1);
    cout << res << endl;
    return 0;
}

